// Gender owns its outfit. Choosing an item never changes identity.
export const WARDROBE_KEY='pogeun-wardrobe-v2';
export const ITEMS={top:[['pink-tee','분홍 반팔','#edb6c8'],['blue-tee','하늘 반팔','#a9d4e9'],['white-tee','기본 흰 반팔','#fff9e9'],['raglan','나그랑 티','#c6d3b3'],['stripes','줄무늬 티','#91b9d1'],['hoodie','라벤더 후드','#c2b5d7'],['cream-hoodie','크림 후드','#e9d7b6'],['crop','복숭아 크롭티','#eab8a6'],['oversized-knit','오트밀 오버핏 니트','#d8c4ad'],['vneck-knit','차콜 브이넥 니트','#62616a'],['cream-vneck','아이보리 브이넥 니트','#e9dfce'],['fine-knit','모카 골지 니트','#ab8e83'],['cardigan','소프트 가디건','#dcaab2']],bottom:[['shorts','기본 반바지','#9bb3ce'],['black-shorts','블랙 숏팬츠','#343439'],['cream-shorts','크림 반바지','#e6d9bb'],['denim','청바지','#7d9dbb'],['trousers','코튼 긴바지','#b5a58f'],['long-skirt','차콜 롱스커트','#55535a'],['satin-long','모카 새틴 롱스커트','#a18a80'],['skirt','미디 스커트','#a99299'],['pleats','잔주름 스커트','#b6c6a0']],shoes:[['sneakers','흰 운동화','#fff8e8'],['pink-shoes','분홍 운동화','#e2afbd'],['blue-shoes','하늘 운동화','#a7c9d5'],['loafers','브라운 로퍼','#ae8260'],['boots','브라운 미들부츠','#92725c'],['black-boots','블랙 롱부츠','#302f33'],['sandals','여름 샌들','#e2cea5']],bag:[['none','가방 벗기','#eee9d8'],['crossbody','작은 크로스백','#bf9876'],['backpack','민트 백팩','#b4c9aa'],['tote','크림 에코백','#eadfc5']],hat:[['none','모자 벗기','#eee9d8'],['straw','밀짚 모자','#e7cc94'],['beret','딸기 베레모','#d89fae'],['cap','하늘 볼캡','#adcddd'],['bow','리본 머리띠','#e6b0bd']],accessory:[['none','악세서리 빼기','#eee9d8'],['glasses','동그란 안경','#a48b75'],['scarf','체크 스카프','#d1a791'],['flower','작은 꽃핀','#f1cb8b'],['heart','하트 목걸이','#e0ada8']]};
export const SLOT_LABELS={top:'상의',bottom:'하의',shoes:'신발',bag:'가방',hat:'모자',accessory:'악세서리'};
export const baseOutfit=gender=>({top:gender==='male'?'blue-tee':'oversized-knit',bottom:gender==='male'?'shorts':'black-shorts',shoes:gender==='male'?'sneakers':'black-boots',bag:'none',hat:'none',accessory:'none'});
export function cleanOutfit(value,gender){const out=baseOutfit(gender);for(const slot in ITEMS)if(ITEMS[slot].some(x=>x[0]===value?.[slot]))out[slot]=value[slot];return out;}
export function restoreWardrobe(raw){let v;try{v=JSON.parse(raw);}catch{}return {gender:v?.gender==='male'?'male':'female',female:cleanOutfit(v?.female,'female'),male:cleanOutfit(v?.male,'male'),looks:Array.isArray(v?.looks)?v.looks.filter(x=>['female','male'].includes(x?.gender)).slice(0,6).map(x=>({gender:x.gender,outfit:cleanOutfit(x.outfit,x.gender)})):[]};}
